/// Write a value using bit_width bits starting at bit_pos
fn writeBits(bytes: []u8, bit_pos: usize, value: u32, bit_width: u5) !void {
    if (bit_width == 0) return;

    var remaining_bits: u5 = bit_width;
    var current_bit = bit_pos;
    var v = value;

