        // bits_in_byte is <= 8, so the shift and mask are well within u16/u8 limits
        const mask: u8 = safe.castTo(u8, (@as(u16, 1) << bits_in_byte) - 1) catch unreachable; // bits_in_byte <= 8, so (1 << bits_in_byte) - 1 <= 255
